const std=@import("std");
export fn power_iteration(v:[*]const i64,n:usize) f64 {if(n!=5)return -1e300;for(0..5)|i|if(v[i]<1 or v[i]>1000)return -1e300;const a=@as(f64,@floatFromInt(v[0]));const b=@as(f64,@floatFromInt(v[1]));const d=@as(f64,@floatFromInt(v[2]));if(a*d<=b*b)return -1e300;var x=@as(f64,@floatFromInt(v[3]));var y=@as(f64,@floatFromInt(v[4]));var previous:f64=0;for(0..100)|it|{const w0=a*x+b*y;const w1=b*x+d*y;const norm=@sqrt(w0*w0+w1*w1);if(norm==0)return -1e300;x=w0/norm;y=w1/norm;const av0=a*x+b*y;const av1=b*x+d*y;const eig=x*av0+y*av1;const error=@abs(eig-previous)/eig;if(error<=1e-12 or it==99)return eig;previous=eig;}return -1e300;}
